const API_BASE=window.VAZ_API_BASE||'';
const TOKEN_KEY='vazPersonal.token';
const app=document.getElementById('app');
const toastEl=document.getElementById('toast');
let token=localStorage.getItem(TOKEN_KEY)||'';
let me=null,view='home',clients=[],ops={clients:[],alerts:[],counts:{}},brand=null,selected=null,selectedOps=null,clientTab='summary',adminData={personals:[],counts:{}},authMode='login',pendingMsg='',aiDraft=false;

const goalNames={hypertrophy:'Hipertrofia',weight_loss:'Emagrecimento',recomp:'RecomposiÃ§Ã£o corporal',strength:'ForÃ§a',conditioning:'Condicionamento','5k':'5 km','10k':'10 km','21k':'Meia maratona','42k':'Maratona'};
const modeNames={hybrid:'HÃ­brido',strength:'MusculaÃ§Ã£o',run:'Corrida'};
const muscleNames={chest:'Peitoral',back:'Costas',shoulders:'Ombros',quads:'QuadrÃ­ceps',hamstrings:'Posteriores',glutes:'GlÃºteos',arms:'BraÃ§os',core:'Core',biceps:'BÃ­ceps',triceps:'TrÃ­ceps',calves:'Panturrilhas'};
const dayNames=['Dom','Seg','Ter','Qua','Qui','Sex','SÃ¡b'];
const safe=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmtDate=v=>{if(!v)return 'â€”';const d=new Date(String(v).length===10?`${v}T12:00:00`:v);return Number.isNaN(d.getTime())?'â€”':d.toLocaleDateString('pt-BR')};
const money=v=>v==null||v===''?'â€”':Number(v).toLocaleString('pt-BR',{style:'currency',currency:'BRL'});
const initials=n=>String(n||'VP').trim().split(/\s+/).slice(0,2).map(x=>x[0]||'').join('').toUpperCase();
function toast(msg){if(!toastEl)return;toastEl.textContent=msg;toastEl.classList.add('show');setTimeout(()=>toastEl.classList.remove('show'),2600)}
function url(path,params={}){const u=new URL(path,API_BASE||location.origin);Object.entries(params).forEach(([k,v])=>v!=null&&u.searchParams.set(k,v));return u.toString()}
async function req(path,{method='GET',body=null,params=null,auth=true}={}){const headers={'Content-Type':'application/json'};if(auth&&token)headers.Authorization=`Bearer ${token}`;const r=await fetch(url(path,params||{}),{method,headers,body:body?JSON.stringify(body):undefined});const data=await r.json().catch(()=>({}));if(r.status===401&&auth){localStorage.removeItem(TOKEN_KEY);token='';me=null}if(!r.ok){const e=new Error(data.message||'NÃ£o foi possÃ­vel concluir esta operaÃ§Ã£o.');e.code=data.error;e.status=r.status;throw e}return data}
const authApi=(action,o={})=>req('/api/personal-auth',{...o,params:{...(o.params||{}),action}});
const vfApi=(action,o={})=>req('/api/vf',{...o,params:{...(o.params||{}),action}});
const opsApi=(action,o={})=>req('/api/personal-ops',{...o,params:{...(o.params||{}),action}});
const adminApi=(action,o={})=>req('/api/admin-v2',{...o,params:{...(o.params||{}),action}});

async function init(){
  if(!token){renderAuth();return}
  try{const d=await authApi('me');me=d.user;if(me.role==='admin'){view='admin-home';await loadAdmin()}else{view='home';await loadPersonal()}render()}catch(e){localStorage.removeItem(TOKEN_KEY);token='';me=null;renderAuth(e.message)}
}
async function loadPersonal(){const [a,b,c]=await Promise.all([vfApi('personal_clients'),opsApi('summary').catch(()=>({clients:[],alerts:[],counts:{}})),req('/api/branding').catch(()=>({branding:null}))]);clients=a.clients||[];ops=b;brand=c.branding||defaultBrand()}
async function loadAdmin(){const d=await adminApi('summary');adminData=d}
function defaultBrand(){return {systemName:'Vaz Fitness',primaryColor:'#f5c400',accentColor:'#151515',backgroundColor:'#ffffff',surfaceColor:'#ffffff',textColor:'#1c1c1c',logoUrl:null}}

function render(){if(!me)return renderAuth();app.innerHTML=me.role==='admin'?renderAdminShell():renderPersonalShell();bindCommon();me.role==='admin'?bindAdmin():bindPersonal()}
function renderAuth(message=''){
  me=null;const reg=authMode==='register';app.innerHTML=`<main class="vp-auth"><section class="vp-auth-card"><div class="vp-brand"><div class="vp-logo">VP</div><div><strong>Vaz Personal</strong><small>Central profissional</small></div></div><h1>${reg?'Criar conta':'Entrar'}</h1><p>${reg?'Cadastre-se para solicitar acesso Ã  plataforma. A conta sÃ³ serÃ¡ liberada apÃ³s aprovaÃ§Ã£o do administrador.':'Entre com seu e-mail. O administrador tambÃ©m pode usar o nome de usuÃ¡rio.'}</p>${pendingMsg?`<div class="vp-pending"><strong>SolicitaÃ§Ã£o enviada</strong><p>${safe(pendingMsg)}</p></div>`:''}${message?`<div class="vp-alert danger"><div><strong>${safe(message)}</strong></div></div>`:''}<form id="authForm" class="vp-auth-form">${reg?'<input name="name" placeholder="Nome completo" required maxlength="80">':''}<input name="identifier" placeholder="${reg?'E-mail':'E-mail ou usuÃ¡rio'}" ${reg?'type="email"':''} required><input name="password" type="password" placeholder="Senha" minlength="8" required><button class="vp-btn primary">${reg?'Enviar solicitaÃ§Ã£o':'Entrar'}</button></form><div class="vp-auth-switch">${reg?'JÃ¡ possui conta?':'Ainda nÃ£o possui conta?'} <button class="vp-link" id="authSwitch">${reg?'Entrar':'Solicitar acesso'}</button></div></section></main>`;
  document.getElementById('authSwitch').onclick=()=>{authMode=reg?'login':'register';pendingMsg='';renderAuth()};
  document.getElementById('authForm').onsubmit=async e=>{e.preventDefault();const fd=new FormData(e.target);try{if(reg){const d=await authApi('register',{method:'POST',body:{name:fd.get('name'),email:fd.get('identifier'),password:fd.get('password')},auth:false});pendingMsg=`Seu cadastro ${d.user?.publicCode||''} estÃ¡ aguardando aprovaÃ§Ã£o. VocÃª poderÃ¡ entrar depois que o administrador liberar seu perfil.`;authMode='login';renderAuth()}else{const d=await authApi('login',{method:'POST',body:{identifier:fd.get('identifier'),password:fd.get('password')},auth:false});token=d.token;localStorage.setItem(TOKEN_KEY,token);me=d.user;if(me.role==='admin'){view='admin-home';await loadAdmin()}else{view='home';await loadPersonal()}if(me.mustChangePassword)view='settings';render()}}catch(err){if(err.code==='approval_pending')pendingMsg=err.message;renderAuth(err.code==='approval_pending'?'':err.message)}};
}

function personalNav(){return [{id:'home',ico:'âŒ‚',label:'InÃ­cio',mobileLabel:'InÃ­cio',sub:'visÃ£o geral'},{id:'students',ico:'â—Ž',label:'Alunos',mobileLabel:'Alunos',sub:'carteira'},{id:'billing',ico:'â—«',label:'Mensalidades',mobileLabel:'Financeiro',sub:'financeiro'},{id:'brand',ico:'âœ¦',label:'Identidade',mobileLabel:'Marca',sub:'sua marca'},{id:'settings',ico:'âš™',label:'ConfiguraÃ§Ãµes',mobileLabel:'Ajustes',sub:'conta e seguranÃ§a'}]}
function adminNav(){return [{id:'admin-home',ico:'âŒ‚',label:'Painel',sub:'plataforma'},{id:'approvals',ico:'âœ“',label:'AprovaÃ§Ãµes',sub:'novos personals'},{id:'personals',ico:'â—Ž',label:'Personals',sub:'ativos e bloqueios'},{id:'admin-billing',ico:'â—«',label:'CobranÃ§as',sub:'vencimentos'},{id:'settings',ico:'âš™',label:'ConfiguraÃ§Ãµes',sub:'conta admin'}]}
function navHtml(items,mobile=false){return items.map(n=>`<button data-view="${n.id}" class="${view===n.id?'active':''}">${mobile?`<span class="ico">${n.ico}</span>${n.mobileLabel||n.label}`:`<span class="ico">${n.ico}</span><span><b>${n.label}</b><small>${n.sub}</small></span>`}</button>`).join('')}
function topHtml(admin=false){return `<header class="vp-top"><div class="vp-brand"><div class="vp-logo">${admin?'A':'VP'}</div><div><strong>${admin?'Admin Vaz':'Vaz Personal'}</strong><small>${admin?'Controle da plataforma':'GestÃ£o profissional'}</small></div></div><button class="vp-btn ghost" data-view="settings">${initials(me.name)}</button></header>`}
function renderPersonalShell(){const items=personalNav();return `<div class="vp-app">${topHtml(false)}<div class="vp-layout"><aside class="vp-side"><nav class="vp-nav">${navHtml(items)}</nav></aside><main class="vp-main">${selected?renderClient():renderPersonalView()}</main></div><nav class="vp-mobile-nav">${navHtml(items,true)}</nav></div>`}
function renderAdminShell(){const items=adminNav();return `<div class="vp-app">${topHtml(true)}<div class="vp-layout"><aside class="vp-side"><nav class="vp-nav">${navHtml(items)}</nav></aside><main class="vp-main">${renderAdminView()}</main></div><nav class="vp-mobile-nav">${navHtml(items,true)}</nav></div>`}
function pageHead(title,sub,actions=''){return `<div class="vp-page-head"><div><h1>${safe(title)}</h1><p>${safe(sub)}</p></div><div class="vp-actions">${actions}</div></div>`}
function badge(label,type='info'){return `<span class="vp-badge ${type}">${safe(label)}</span>`}
function statusBadge(s){return s==='approved'?badge('Ativo','ok'):s==='suspended'?badge('Suspenso','danger'):badge('Aguardando','warn')}

function renderPersonalView(){if(view==='students')return renderStudents();if(view==='billing')return renderBilling();if(view==='brand')return renderBrand();if(view==='settings')return renderSettings();return renderHome()}
function renderHome(){const active=clients.filter(x=>x.status==='approved').length,pending=clients.filter(x=>x.status==='pending').length;return `${pageHead('Bom dia, '+(me.name?.split(' ')[0]||'Personal'),'O que precisa da sua atenÃ§Ã£o hoje?')}<section class="vp-grid four"><div class="vp-card compact vp-stat"><span>Alunos</span><strong>${clients.length}</strong></div><div class="vp-card compact vp-stat"><span>Ativos</span><strong>${active}</strong></div><div class="vp-card compact vp-stat"><span>Treinos a revisar</span><strong>${ops.counts?.cycleReview||0}</strong></div><div class="vp-card compact vp-stat"><span>Mensalidades pendentes</span><strong>${ops.counts?.billingPending||0}</strong></div></section><section class="vp-grid two vp-section"><div class="vp-card"><div class="vp-page-head"><div><h2>AtenÃ§Ãµes</h2><p>Treinos, pagamentos e liberaÃ§Ãµes.</p></div></div>${pending?`<div class="vp-alert warn"><span>ðŸ‘¤</span><div><strong>${pending} aluno(s) aguardando liberaÃ§Ã£o</strong><small>Revise cadastro e plano antes de liberar.</small></div></div>`:''}${(ops.alerts||[]).slice(0,6).map(a=>`<button class="vp-alert ${a.severity==='danger'?'danger':'warn'}" data-open="${a.athleteId}" style="width:100%;text-align:left;border-style:solid"><span>${a.kind==='billing'?'ðŸ’³':'â±'}</span><div><strong>${safe(a.name)}</strong><small>${safe(a.message)}</small></div></button>`).join('')||(!pending?'<div class="vp-empty">Nenhuma pendÃªncia importante agora.</div>':'')}</div><div class="vp-card"><div class="vp-page-head"><div><h2>AÃ§Ãµes rÃ¡pidas</h2><p>Atalhos do dia a dia.</p></div></div><div class="vp-grid two"><button class="vp-btn primary" data-view="students">+ Vincular aluno</button><button class="vp-btn ghost" data-view="billing">Mensalidades</button><button class="vp-btn ghost" data-view="brand">Personalizar sistema</button><button class="vp-btn dark" id="refreshPersonal">Atualizar dados</button></div></div></section><section class="vp-card vp-section"><div class="vp-page-head"><div><h2>Alunos recentes</h2><p>Acesse treino, evoluÃ§Ã£o e gestÃ£o.</p></div><button class="vp-btn ghost" data-view="students">Ver todos</button></div>${clientRows(clients.slice(0,6))}</section>`}
function clientRows(list){if(!list.length)return '<div class="vp-empty">Nenhum aluno vinculado.</div>';return list.map(c=>`<div class="vp-row"><div class="vp-avatar">${initials(c.name)}</div><div class="vp-row-main"><strong>${safe(c.name)}</strong><small><span class="vp-code">${safe(c.publicCode)}</span> â€¢ ${safe(goalNames[c.summary?.goal]||c.summary?.goal||'perfil')}</small></div>${statusBadge(c.status)}<button class="vp-btn ghost" data-open="${c.id}">Abrir</button></div>`).join('')}
function renderStudents(){return `${pageHead('Meus alunos','Carteira completa e solicitaÃ§Ãµes.',`<button class="vp-btn primary" id="claimBtn">+ CÃ³digo ID</button>`)}<section class="vp-card">${clientRows(clients)}</section>`}
function renderBilling(){const list=ops.clients||[];return `${pageHead('Mensalidades','Controle financeiro dos seus alunos.')}<section class="vp-grid three"><div class="vp-card compact vp-stat"><span>Configuradas</span><strong>${list.filter(x=>x.billing?.configured).length}</strong></div><div class="vp-card compact vp-stat"><span>Pendentes</span><strong>${list.filter(x=>x.billing?.status==='pending').length}</strong></div><div class="vp-card compact vp-stat"><span>Sem vencimento</span><strong>${list.filter(x=>!x.billing?.configured).length}</strong></div></section><section class="vp-card vp-section">${list.length?list.map(x=>`<div class="vp-row"><div class="vp-avatar">${initials(x.name)}</div><div class="vp-row-main"><strong>${safe(x.name)}</strong><small>${x.billing?.configured?`Vence ${fmtDate(x.billing.nextDueDate)} â€¢ ${money(x.billing.amount)}`:'Mensalidade nÃ£o configurada'}</small></div>${x.billing?.status==='pending'?badge('Pendente','danger'):x.billing?.configured?badge('Em dia','ok'):badge('Configurar','warn')}<button class="vp-btn ghost" data-open="${x.id}" data-tab-target="management">Gerenciar</button></div>`).join(''):'<div class="vp-empty">Nenhum aluno para exibir.</div>'}</section>`}
function renderBrand(){const b=brand||defaultBrand();return `${pageHead('Identidade do sistema','Crie a experiÃªncia que seus alunos verÃ£o.')}<section class="vp-grid two"><form class="vp-card" id="brandForm"><h2>Sua marca</h2><p>Nome, cores e logo sÃ£o sincronizados com os alunos liberados.</p><div class="vp-form-grid"><div class="vp-field"><label>Nome do sistema</label><input name="systemName" value="${safe(b.systemName)}" maxlength="50"></div><div class="vp-field"><label>Logo (URL HTTPS)</label><input name="logoUrl" value="${safe(b.logoUrl||'')}" placeholder="https://..."></div><div class="vp-field"><label>Cor principal</label><input name="primaryColor" type="color" value="${safe(b.primaryColor)}"></div><div class="vp-field"><label>Contraste</label><input name="accentColor" type="color" value="${safe(b.accentColor)}"></div><div class="vp-field"><label>Fundo</label><input name="backgroundColor" type="color" value="${safe(b.backgroundColor)}"></div><div class="vp-field"><label>Cards</label><input name="surfaceColor" type="color" value="${safe(b.surfaceColor)}"></div><div class="vp-field"><label>Texto</label><input name="textColor" type="color" value="${safe(b.textColor)}"></div></div><div class="vp-actions" style="margin-top:12px"><button class="vp-btn primary">Salvar identidade</button></div></form><div class="vp-card"><h2>PrÃ©via no celular</h2><p>A prÃ©via agora ocupa a largura correta e simula o app do aluno.</p><div class="vp-phone-preview-wrap"><div class="vp-phone" id="brandPreview" style="--preview-bg:${safe(b.backgroundColor)};--preview-surface:${safe(b.surfaceColor)};--preview-primary:${safe(b.primaryColor)};--preview-text:${safe(b.textColor)}"><div class="vp-phone-bar"></div><div class="vp-phone-screen"><div class="vp-phone-brand"><div class="vp-phone-brandmark">${b.logoUrl?'â—Ž':'VF'}</div><div><strong id="previewName">${safe(b.systemName)}</strong><small style="display:block;opacity:.6">Seu treino de hoje</small></div></div><div class="vp-phone-card"><small style="opacity:.6">TREINO DE HOJE</small><h3 style="margin:5px 0">Peito + trÃ­ceps</h3><p style="margin:0;opacity:.65">6 exercÃ­cios â€¢ 55 min</p><div class="vp-phone-button">Iniciar treino</div></div><div class="vp-phone-card"><small style="opacity:.6">EVOLUÃ‡ÃƒO</small><h3 style="margin:5px 0">ConsistÃªncia 82%</h3><p style="margin:0;opacity:.65">VocÃª estÃ¡ evoluindo bem.</p></div></div></div></div></div></section>`}
function renderSettings(){return `${pageHead('ConfiguraÃ§Ãµes','Cadastro, alunos, seguranÃ§a e sessÃ£o.')} ${me.mustChangePassword?`<div class="vp-alert danger"><span>ðŸ”</span><div><strong>Troque sua senha temporÃ¡ria</strong><small>Esta alteraÃ§Ã£o Ã© obrigatÃ³ria para proteger o acesso administrativo.</small></div></div>`:''}<section class="vp-grid two vp-section"><form class="vp-card" id="profileForm"><h2>Meu cadastro</h2><p>InformaÃ§Ãµes da sua conta.</p><div class="vp-field"><label>Nome</label><input name="name" value="${safe(me.name)}"></div><div class="vp-field" style="margin-top:8px"><label>E-mail</label><input name="email" type="email" value="${safe(me.email)}"></div>${me.username?`<div class="vp-kv"><span>UsuÃ¡rio</span><strong>${safe(me.username)}</strong></div>`:''}<div class="vp-kv"><span>CÃ³digo</span><strong class="vp-code">${safe(me.publicCode)}</strong></div><button class="vp-btn primary" style="margin-top:10px">Salvar cadastro</button></form><div class="vp-card"><h2>GestÃ£o</h2><div class="vp-settings-list">${me.role==='personal'?`<button class="vp-settings-item" data-view="students" style="border-left:0;border-right:0;border-bottom:0;background:none;text-align:left"><span class="ico">â—Ž</span><div><strong>GestÃ£o de alunos</strong><small>Carteira, planos e acessos</small></div><span>â€º</span></button><button class="vp-settings-item" data-view="billing" style="border-left:0;border-right:0;border-bottom:0;background:none;text-align:left"><span class="ico">â—«</span><div><strong>Mensalidades</strong><small>Pagamentos dos alunos</small></div><span>â€º</span></button><button class="vp-settings-item" data-view="brand" style="border-left:0;border-right:0;border-bottom:0;background:none;text-align:left"><span class="ico">âœ¦</span><div><strong>Identidade do sistema</strong><small>Nome, cores e logo</small></div><span>â€º</span></button>`:`<button class="vp-settings-item" data-view="personals" style="border-left:0;border-right:0;border-bottom:0;background:none;text-align:left"><span class="ico">â—Ž</span><div><strong>Gerenciar personals</strong><small>AprovaÃ§Ãµes e bloqueios</small></div><span>â€º</span></button>`}</div></div></section><section class="vp-grid two vp-section"><form class="vp-card" id="passwordForm"><h2>Alterar senha</h2><div class="vp-field"><label>Senha atual</label><input name="current" type="password" required></div><div class="vp-field" style="margin-top:8px"><label>Nova senha</label><input name="next" type="password" minlength="8" required></div><button class="vp-btn dark" style="margin-top:10px">Alterar senha</button></form><div class="vp-card"><h2>SessÃ£o</h2><p>O botÃ£o de saÃ­da fica somente aqui, longe das aÃ§Ãµes rotineiras.</p><button class="vp-btn danger" id="logoutBtn">Sair da conta</button></div></section>`}

async function openClient(id,tab='summary'){try{const [a,b]=await Promise.all([vfApi('personal_client',{params:{athleteId:id}}),opsApi('client',{params:{athleteId:id}})]);selected=a;selectedOps=b;clientTab=tab;view='students';render()}catch(e){toast(e.message)}}
function renderClient(){const a=selected.athlete,st=selected.state||{},p=st.profile||{};return `${pageHead(a.name,`${modeNames[p.mode]||'Perfil'} â€¢ ${goalNames[p.goal]||p.goal||'Objetivo nÃ£o informado'}`,`<button class="vp-btn ghost" id="backClients">â† Alunos</button>`)}<div class="vp-tabs">${[['summary','Resumo'],['plan','Plano'],['evolution','EvoluÃ§Ã£o'],['management','GestÃ£o'],['access','Acesso']].map(([id,l])=>`<button class="vp-tab ${clientTab===id?'active':''}" data-client-tab="${id}">${l}</button>`).join('')}</div>${clientTab==='plan'?renderClientPlan():clientTab==='evolution'?renderClientEvolution():clientTab==='management'?renderClientManagement():clientTab==='access'?renderClientAccess():renderClientSummary()}`}
function renderClientSummary(){const st=selected.state||{},p=st.profile||{},sessions=st.sessions||[],runs=st.runSessions||[],body=st.bodyMeasurements||[],weight=body.at(-1)?.weight||p.weight||'â€”';return `<section class="vp-grid four"><div class="vp-card compact vp-stat"><span>Peso</span><strong>${weight==='â€”'?'â€”':`${weight} kg`}</strong></div><div class="vp-card compact vp-stat"><span>MusculaÃ§Ã£o</span><strong>${sessions.length}</strong></div><div class="vp-card compact vp-stat"><span>Corridas</span><strong>${runs.length}</strong></div><div class="vp-card compact vp-stat"><span>Status</span><strong style="font-size:14px">${selected.athlete.status==='approved'?'Ativo':selected.athlete.status==='suspended'?'Suspenso':'Aguardando'}</strong></div></section><section class="vp-grid two vp-section"><div class="vp-card"><h2>Perfil</h2>${[['Idade',p.age?`${p.age} anos`:'â€”'],['Altura',p.height?`${p.height} cm`:'â€”'],['Modalidade',modeNames[p.mode]||'â€”'],['Objetivo',goalNames[p.goal]||p.goal||'â€”'],['Dias/semana',p.days||'â€”'],['Prioridade',muscleNames[p.priorityMuscle]||p.priorityMuscle||'â€”']].map(([k,v])=>`<div class="vp-kv"><span>${k}</span><strong>${safe(v)}</strong></div>`).join('')}</div><div class="vp-card"><div class="vp-page-head"><div><h2>AION para o personal</h2><p>AnÃ¡lise dos dados recentes.</p></div><button class="vp-btn dark" id="analyzeClient">Analisar</button></div><div id="aiBox" class="vp-alert warn"><div><strong>AION IA</strong><small>Use a anÃ¡lise como apoio Ã  sua decisÃ£o profissional.</small></div></div></div></section>`}
function renderClientPlan(){const plan=Array.isArray(selected.plan?.plan)?selected.plan.plan:[];return `<section class="vp-card"><div class="vp-page-head"><div><h2>Plano de treino</h2><p>VersÃ£o ${selected.plan?.plan_version||0}${aiDraft?' â€¢ rascunho gerado pela AION':''}</p></div><div class="vp-actions"><button class="vp-btn ghost" id="addDay">+ Dia</button><button class="vp-btn primary" id="savePlan">Salvar</button></div></div><div id="planDays">${plan.map((d,i)=>renderPlanDay(d,i)).join('')||'<div class="vp-empty">Nenhum treino cadastrado.</div>'}</div><div class="vp-field" style="margin-top:10px"><label>OrientaÃ§Ãµes do personal</label><textarea id="planNotes" rows="3">${safe(selected.plan?.notes||'')}</textarea></div></section>`}
function renderPlanDay(d,i){const run=d.type==='run';return `<div class="vp-card compact" data-plan-day data-index="${i}" data-id="${safe(d.id||'')}" style="margin-top:9px;background:#fafaf8"><div class="vp-form-grid"><div class="vp-field"><label>Dia</label><select data-day="day">${dayNames.map((x,idx)=>`<option value="${idx}" ${Number(d.day)===idx?'selected':''}>${x}</option>`).join('')}</select></div><div class="vp-field"><label>Tipo</label><select data-day="type"><option value="strength" ${!run?'selected':''}>MusculaÃ§Ã£o</option><option value="run" ${run?'selected':''}>Corrida</option></select></div><div class="vp-field"><label>Nome</label><input data-day="name" value="${safe(d.name||'Treino')}"></div><div class="vp-field"><label>DuraÃ§Ã£o (min)</label><input data-day="duration" type="number" value="${Number(d.duration)||60}"></div></div>${run?`<div class="vp-form-grid" style="margin-top:8px"><div class="vp-field"><label>Pace</label><input data-day="pace" value="${safe(d.pace||'')}"></div><div class="vp-field"><label>Intensidade</label><input data-day="intensity" value="${safe(d.intensity||'Leve')}"></div></div>`:`<div style="margin-top:8px">${(d.exercises||[]).map((e,j)=>renderExercise(e,i,j)).join('')}<button class="vp-btn ghost" data-add-ex="${i}" style="margin-top:6px">+ ExercÃ­cio</button></div>`}<div class="vp-actions" style="margin-top:8px"><button class="vp-btn danger" data-remove-day="${i}">Excluir dia</button></div></div>`}
